static void upload(Image &image,Buffer &buffer,size_t offset){image.dependency(VK_ACCESS_TRANSFER_WRITE_BIT);VkBufferImageCopy c{};c.bufferOffset=offset;c.imageSubresource={VK_IMAGE_ASPECT_COLOR_BIT,0,0,1};c.imageExtent={image.width,image.height,1};vkCmdCopyBufferToImage(command,buffer.buffer,image.image,VK_IMAGE_LAYOUT_GENERAL,1,&c);}
