static void bloom_test(const char*root){
 Image input(VK_FORMAT_R32G32B32A32_SFLOAT,8,8),glow(VK_FORMAT_R32G32B32A32_SFLOAT,8,8),output(VK_FORMAT_R32G32B32A32_SFLOAT,1,1,VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT);
 Draw box(input,glow,output,root,"bloom_box.frag"),karis(input,glow,output,root,"bloom_karis.frag");
 for(auto*d:{&box,&karis}){d->cb1.host[0]=.587f;d->cb1.host[1]=.114f;d->cb3.host[4]=0;d->cb3.host[5]=1.f/3;d->cb3.host[6]=0;d->cb3.host[7]=1;d->cb3.host[11]=1;float offsets[8]={-.25f,-.25f,.25f,-.25f,-.25f,.25f,.25f,.25f};memcpy(d->cb3.host+12,offsets,sizeof offsets);}
 std::vector<float> flat(8*8*4);for(unsigned i=0;i<64;i++){flat[i*4]=.25f;flat[i*4+1]=.5f;flat[i*4+2]=.75f;flat[i*4+3]=1;}
 auto a=render(box,input,glow,output,flat),b=render(karis,input,glow,output,flat);float luma=.125f*.299f+.25f*.587f+.375f*.114f;CHECK(std::abs(a[0]-.125f/(1+luma))<1e-5f);for(unsigned i=0;i<4;i++)CHECK(std::abs(a[i]-b[i])<1e-5f);
 float minimum=100,maximum=0;for(unsigned phase=0;phase<8;phase++){std::vector<float> pulse(8*8*4);for(unsigned i=0;i<64;i++)pulse[i*4+3]=1;for(unsigned c=0;c<3;c++)pulse[(phase*8+phase)*4+c]=64;
  a=render(box,input,glow,output,pulse);b=render(karis,input,glow,output,pulse);CHECK(a[0]>.45f&&a[0]<.55f&&b[0]<a[0]*.25f);minimum=std::min(minimum,a[0]);maximum=std::max(maximum,a[0]);}
 CHECK(maximum-minimum<1e-5f);printf("BLOOM full-footprint 8 phases maxDelta=%g, flat oracle and isolated glint Karis suppression pass\n",maximum-minimum);
}
static void tent_test(const char*root){Image input(VK_FORMAT_R32G32B32A32_SFLOAT,9,9),glow(VK_FORMAT_R32G32B32A32_SFLOAT,9,9),output(VK_FORMAT_R32G32B32A32_SFLOAT,9,9,VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT);Draw tent(input,glow,output,root,"bloom_tent.frag");tent.cb3.host[6]=tent.cb3.host[7]=1.f/9;
 std::vector<float> pixels(9*9*4,.25f);auto result=render(tent,input,glow,output,pixels);for(unsigned i=0;i<81;i++)CHECK(std::abs(result[i*4]-.25f)<1e-6f);
 std::fill(pixels.begin(),pixels.end(),0);pixels[(4*9+4)*4]=1;result=render(tent,input,glow,output,pixels);double sum=0;for(unsigned i=0;i<81;i++)sum+=result[i*4];CHECK(std::abs(sum-1)<1e-5&&std::abs(result[(4*9+4)*4]-.25)<1e-6);puts("BLOOM normalized tent constant and impulse energy pass");}
static void gather_test(const char*root){Image input(VK_FORMAT_R32G32B32A32_SFLOAT,8,8),glow(VK_FORMAT_R32G32B32A32_SFLOAT,8,8),output(VK_FORMAT_R32G32B32A32_SFLOAT,1,1,VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT);Draw gather(input,glow,output,root,"gather.frag");std::vector<float> pixels(8*8*4);for(unsigned y=0;y<8;y++)for(unsigned x=0;x<8;x++)pixels[(y*8+x)*4]=(x+10*y)*.01f;
 float expected[2][4]={{.43f,.44f,.34f,.33f},{.53f,.55f,.35f,.33f}};for(unsigned scale=1;scale<=2;scale++){gather.cb3.host[0]=gather.cb3.host[1]=(float)scale;auto result=render(gather,input,glow,output,pixels);for(unsigned c=0;c<4;c++)CHECK(std::abs(result[c]-expected[scale-1][c])<1e-5f);}Image mip_input(VK_FORMAT_R32G32B32A32_SFLOAT,8,8,0,2);Draw lod_gather(mip_input,glow,output,root,"gather.frag",false,1.f);for(unsigned scale=1;scale<=2;scale++){lod_gather.cb3.host[0]=lod_gather.cb3.host[1]=(float)scale;auto result=render(lod_gather,mip_input,glow,output,pixels);printf("GATHER_LOD scale=%u values=%g,%g,%g,%g\n",scale,result[0],result[1],result[2],result[3]);for(unsigned c=0;c<4;c++)CHECK(std::abs(result[c]-expected[scale-1][c])<1e-5f);}puts("GATHER native/2x footprint, ordering, and nonzero sampler minLod exact GPU oracle pass");}
static void feedback_test(const char*root){if(!renderer_feedback_feature){puts("SKIP native feedback GPU: optional feature unavailable (copy policy covered by production recorder)");return;}
 Image input(VK_FORMAT_R32G32B32A32_SFLOAT,8,8,VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT|VK_IMAGE_USAGE_ATTACHMENT_FEEDBACK_LOOP_BIT_EXT),glow(VK_FORMAT_R32G32B32A32_SFLOAT,8,8),output(VK_FORMAT_R32G32B32A32_SFLOAT,8,8,VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT);Draw feedback(input,glow,output,root,"feedback.frag",true);std::vector<float> pixels(8*8*4);for(unsigned i=0;i<64;i++){pixels[i*4]=i*.01f;pixels[i*4+1]=.25f;pixels[i*4+2]=.5f;pixels[i*4+3]=1;}
 auto result=render(feedback,input,glow,output,pixels);for(unsigned i=0;i<pixels.size();i++)CHECK(std::abs(result[i]-pixels[i])<1e-5f);{feedback.load_clear=true;result=render(feedback,input,glow,output,pixels);float clear[4]={.125f,.25f,.5f,1};for(unsigned i=0;i<result.size();i++)CHECK(std::abs(result[i]-clear[i%4])<1e-5f);}puts("FEEDBACK native extension+feature+usage+pipelineflag+layout+descriptor read-only color GPU exact readback pass");}
